"""True-scale building checks (ref Y1b): generated by python -m sim.scenes.make_building (minutes of
physics, so CI checks the committed sim/scenes/building.xml rather than regenerating it)."""

import mujoco
import numpy as np
import pytest

from sim import aftershock, breakage, scene
from sim.scenes.make_building import supported
from sim.world import World, casualties

LABELS = {"column", "slab", "wall", "stairs", "rubble", "furniture"}


@pytest.fixture(scope="module")
def building():
    return scene.load(scene.BUILDING)


def _free(m, body):
    return m.body_dofnum[body] > 0


def test_pieces_labels_and_scale(building):
    m, d = building
    blocks = scene.blocks(m, d)
    assert len(blocks) >= 250                                   # hundreds of pieces
    assert {b["label"] for b in blocks} <= LABELS
    assert {"column", "slab", "wall", "stairs", "rubble"} <= {b["label"] for b in blocks}
    assert max(b["pos"][2] for b in blocks) > 5.5               # upper storeys still stand
    # True-scale robots from sim/robots, attached outside the south door.
    assert m.body_mocapid[m.body("scout/scout").id] >= 0
    assert m.body_mocapid[m.body("responder").id] >= 0


def test_real_time_budget(building):
    """Frozen ruins are fixed to the floor plate; only the hazards stay live, so it runs in real time."""
    m, _ = building
    live = [i for i in scene.block_ids(m) if _free(m, i)]
    assert 5 <= len(live) <= 40
    assert m.opt.enableflags & mujoco.mjtEnableBit.mjENBL_SLEEP


def test_breakable_welds(building):
    m, _ = building
    b = breakage.Breaker(m)
    assert b.active and len(b.force) == m.neq
    assert b.force[m.equality("plate_to_ground").id] == 0          # the ground weld never breaks
    assert (b.force > 0).sum() >= 5


def test_casualties_in_voids(building):
    m, d = building
    found = casualties(m)
    assert [c[0] for c in found] == ["c1", "c2", "c3", "c4"]
    assert found[0][2] == 0.0                                      # c1 silent
    for name, g, _voice in found[1:]:
        p = d.geom_xpos[g].copy()
        up = mujoco.mj_ray(m, d, np.array([p[0], p[1], 0.05]), np.array([0, 0, 1.0]), None, 1,
                           int(m.geom_bodyid[g]), np.zeros(1, np.int32))
        assert 0.3 < up < 1.6, f"{name} is not under a low roof ({up:.2f} m)"


def test_front_door_fits_the_robots(building):
    m, d = building
    # Across the south door (x 1.55..2.45 at y = 0), at 1 m height: nothing for 0.85 m.
    dist = mujoco.mj_ray(m, d, np.array([1.57, 0.0, 1.0]), np.array([1.0, 0, 0]), None, 1, -1,
                         np.zeros(1, np.int32))
    assert dist < 0 or dist > 0.85


def test_frozen_rubble_rests_on_something(building):
    """Every loose piece (rubble, furniture) rests on the floor or on something within 0.3 m below it
    (slabs and columns hang on their columns and welds, so they are not checked this way)."""
    m, d = building
    loose = [b for b in scene.blocks(m, d) if b["label"] in ("rubble", "furniture")]
    floating = [b["id"] for b in loose if not supported(m, d, m.body(b["id"]).id)]
    assert len(loose) >= 150 and not floating, f"floating pieces: {floating}"


def test_stands_still_then_the_aftershock_breaks_the_cracked_bay():
    w = World(path=scene.BUILDING, render=False)
    live = [i for i in scene.block_ids(w.m) if _free(w.m, i)]
    start = w.d.xpos[live].copy()
    for _ in range(20):
        w.tick(0.1)
    assert np.linalg.norm(w.d.xpos[live] - start, axis=1).max() < 0.1      # loose rubble may settle a little
    assert all(w.d.eq_active[i] for i in range(w.m.neq) if w.breaker.force[i] > 0)   # nothing breaks at rest
    predicted = list(w.would_move)
    assert predicted and all(_free(w.m, w.m.body(n).id) for n in predicted)
    assert predicted == aftershock.unstable_xy(w.m, w.d)[1]               # same inputs, same answer
    w.trigger_aftershock()
    events = []
    for _ in range(31):
        events += w.tick(0.1)
    assert len(events) == 1 and events[0][0] == "world/change"
    moved = events[0][1]["moved_blocks"]
    assert set(moved) & set(predicted)
    assert any(not w.d.eq_active[i] for i in range(w.m.neq) if w.breaker.force[i] > 0)   # welds broke


def test_true_scale_scout_senses_and_drives_in():
    w = World(path=scene.BUILDING, render=False)
    msg = w.sensors_message(camera=False)
    assert msg["pose"]["pos"][2] == pytest.approx(0.26, abs=0.01)        # LiDAR height on the LIMO
    assert len(msg["lidar"]) == 360 and np.array(msg["thermal"]).shape == (12, 16)
    w.goto({"target": [2.0, 1.2, 0.0], "reason": "in through the front door"})
    for _ in range(150):
        w.tick(0.1)
        if w.state != "moving":
            break
    assert w.state == "arrived", (w.state, w.pos)
